// Lato (SIL Open Font License), recortada a Latin-1: letras con tilde, ñ, °, ·, •, …
// Para los PDF de jsPDF, que sólo trae Helvetica/Times/Courier. La original pesa
// 650 KB por variante; recortada, unos 45 KB. Se usa en la orden de compra (V.63).
import type jsPDF from 'jspdf'

export const LatoRegular = ''
export const LatoBold = ''
export const LatoItalic = ''

/** Registra Lato en el documento: setFont('Lato', 'normal' | 'bold' | 'italic') */
export function registrarLato(doc: jsPDF) {
  doc.addFileToVFS('Lato-Regular.ttf', LatoRegular)
  doc.addFont('Lato-Regular.ttf', 'Lato', 'normal')
  doc.addFileToVFS('Lato-Bold.ttf', LatoBold)
  doc.addFont('Lato-Bold.ttf', 'Lato', 'bold')
  doc.addFileToVFS('Lato-Italic.ttf', LatoItalic)
  doc.addFont('Lato-Italic.ttf', 'Lato', 'italic')
}
